preConditionHook:
// Volatility-regime switch: off while the ATR is above K x its own N-bar
// average. NEGATE the placement for the opposite regime (off while volatility
// is compressed) -- Negate applies to Switch placements like any other.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator: seeded with a
// full N-term sum on the study's first calculated bar, thereafter
// S += TrueRange; S -= TrueRange[Length], re-seeding when the length changes.
// AtrProfitTarget is the reference and carries the measurement notes; the
// re-seed and the TWO-statement update are both load-bearing.
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
// EL: Average(atrValue, avgLookback) reads the atrValue VARIABLE's own
// history, which holds 0 before the strategy's first evaluated bar. So for
// roughly the first avgLookback bars the average is diluted by zeros and the
// ratio is inflated -- with K = 1.5 the switch is ON (blocking) for about
// the first avgLookback / K evaluated bars (ratio ~ N/k at bar k). That is EL's behaviour,
// mirrored with a zero-seeded ring buffer (BarRangeAboveStd), re-seeded if
// the length changes. Average() is Summation()/Length and Summation adds
// NEWEST-FIRST ([0] .. [N-1], the bollingerband row), so the ring is read
// newest-first rather than in storage order.
if (atrHistory.size() != (std::size_t)(int)avgLookback) {
    atrHistory.assign((std::size_t)(int)avgLookback, 0.0);
    atrCursor = 0;
}
atrHistory[atrCursor] = atr;
atrCursor = (atrCursor + 1) % atrHistory.size();
atrMean = 0.0;
for (std::size_t k = 0; k < atrHistory.size(); ++k) {
    atrMean += atrHistory[(atrCursor + atrHistory.size() - 1 - k) % atrHistory.size()];
}
atrMean /= (int)avgLookback;
